WITH base AS (SELECT id, name, email, country, signup_date, is_active, credit_limit, age, COALESCE(email, 'Unknown') AS email_filled FROM customers WHERE segment IS NOT NULL AND is_active = TRUE) SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, COUNT_IF(country = 'UK') AS uk_events, BIT_OR(age) AS age_bit_or, COUNT(*) AS num_rows, COUNT(CASE WHEN country = 'SG' THEN 1 END) AS sg_count, SUM(CASE WHEN country = 'SG' THEN age ELSE 0 END) AS sg_age FROM base GROUP BY DATE_TRUNC('YEAR', signup_date) ORDER BY year_start;
